using System;using System.Linq;using System.Drawing;using System.Windows.Forms;namespace ServiceTool{internal static class LauncherFooterVisualTests{static System.Collections.Generic.IEnumerable<Control> Walk(Control p){foreach(Control c in p.Controls){yield return c;foreach(var x in Walk(c))yield return x;}}[STAThread]static int Main(){try{int n=0;foreach(bool dark in new[]{true,false})using(var f=new ManagerHub()){f.SetTheme(dark,false);f.Show();for(int i=0;i<15;i++)Application.DoEvents();var controls=Walk(f).ToArray();var b=new[]{controls.OfType<Button>().Single(x=>x.Text=="ⓘ"),controls.OfType<Button>().Single(x=>x.Text=="Инструкция"),controls.OfType<Button>().Single(x=>x.Text=="Скачать комплект"),controls.OfType<Button>().Single(x=>x.Text=="Закрыть программу")};if(b[0].Width!=b[0].Height)throw new Exception("Info not square");n++;if(b.Skip(1).Select(x=>x.Size).Distinct().Count()!=1)throw new Exception("Unequal action sizes");n++;int[] gaps=Enumerable.Range(0,3).Select(i=>b[i+1].PointToScreen(Point.Empty).X-b[i].PointToScreen(new Point(b[i].Width,0)).X).ToArray();if(gaps.Max()-gaps.Min()>1||gaps.Max()>b[0].Height/2)throw new Exception("Uneven or oversized gaps: "+String.Join(",",gaps));n++;using(var image=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"launcher-fixed-"+dark+".png"));}}Console.WriteLine("PASS: "+n+" launcher square/equal buttons/compact equal gap checks, both themes.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}}